import std.collection.HashMap
import std.time.DateTime

class AccessGatewayFilter {
    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let path = request.get("path") as? String
        let method = request.get("method") as? String

        if path == None || method == None {
            return false
        }

        if !is_start_with(path as String) {
            return false
        }

        let user_opt = get_jwt_user(request)
        if user_opt.isSome() {
            set_current_user_info_and_log(user_opt.unwrap())
            return true
        }

        return false
    }

    public func is_start_with(request_uri: String): Bool {
        return request_uri.startsWith("/api") || request_uri.startsWith("/login")
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request.get("headers") as? HashMap<String, Any>
        if headers == None {
            return None
        }

        let auth = headers.get().get("Authorization") as? HashMap<String, Any>
        if auth == None {
            return None
        }

        let user = auth.get("user") as? HashMap<String, Any>
        let jwt = auth.get("jwt") as? String

        if user == None || jwt == None {
            return None
        }

        let expected_jwt = user.get("name") as? String
        if expected_jwt == None {
            return None
        }

        let current_date = DateTime.now().format("yyyy-MM-dd")
        if jwt == expected_jwt + current_date {
            return Some(user as HashMap<String, Any>)
        }

        return None
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let name = user.get("name") as? String
        let timestamp = DateTime.now().format("yyyy-MM-dd HH:mm:ss")
        let log_entry = "[ACCESS_LOG] User: ${name}, Time: ${timestamp}"
        println(log_entry)
    }
}

