import std.collection.HashMap
import std.collection.ArrayList
import std.unicode.UnicodeStringExtension

class AutomaticGuitarSimulator {

    let play_text: String

    public init(text: String) {
        this.play_text = text
    }

    public func interpret(display!: Bool = false): ArrayList<HashMap<String, String>> {
        let result = ArrayList<HashMap<String, String>>()
        let text = this.play_text.trim()
        if text.isEmpty() {
            return result
        }

        let regex = Regex(pattern: "([A-G][#m]?(?:m7|maj7|7|add9)?)\\s*(\\d+)", flags: [])
        let matches = regex.find(input: text, group: true)

        var remaining = text
        while true {
            let match = regex.find(input: remaining, group: true)
            if match.isNone() {
                break
            }
            let m = match.unwrap()
            let chord = m.group(index: 1)
            let tune = m.group(index: 2)
            let entry = HashMap<String, String>()
            entry["Chord"] = chord
            entry["Tune"] = tune
            result.add(entry)
            if display {
                this.display(key: chord, value: tune)
            }
            let endIndex = m.end()
            if endIndex >= remaining.size() {
                break
            }
            remaining = remaining.substring(endIndex)
        }

        return result
    }

    public func display(key: String, value: String): String {
        let output = "Normal Guitar Playing -- Chord: ${key}, Play Tune: ${value}"
        return output
    }
}

