class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    public static func add(num1: String, num2: String): String {
        /*
        Adds two big numbers.
        :param num1: The first number to add,String.
        :param num2: The second number to add,String.
        :return: The sum of the two numbers,String.
        >>> BigNumCalculator.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'

        */
        let len1 = num1.length()
        let len2 = num2.length()
        let maxLen = max(len1, len2)
        var carry = 0
        var result = ""
        for (i in 0..maxLen - 1) {
            var digit1 = 0
            var digit2 = 0
            if (i < len1) {
                digit1 = num1[len1 - 1 - i].toDigit()
            }
            if (i < len2) {
                digit2 = num2[len2 - 1 - i].toDigit()
            }
            let total = digit1 + digit2 + carry
            result = String(total % 10) + result
            carry = total / 10
        }
        if (carry > 0) {
            result = String(carry) + result
        }
        return result
    }

    public static func subtract(num1: String, num2: String): String {
        /*
        Subtracts two big numbers.
        :param num1: The first number to subtract,String.
        :param num2: The second number to subtract,String.
        :return: The difference of the two numbers,String.
        >>> BigNumCalculator.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'

        */
        let cmp = compareAbs(num1, num2)
        if (cmp == 0) {
            return "0"
        }
        var result = ""
        var borrow = 0
        let (big, small) = if (cmp > 0) { (num1, num2) } else { (num2, num1) }
        let len1 = big.length()
        let len2 = small.length()
        for (i in 0..len1 - 1) {
            var digit1 = big[len1 - 1 - i].toDigit()
            var digit2 = if (i < len2) { small[len2 - 1 - i].toDigit() } else { 0 }
            let diff = digit1 - digit2 - borrow
            if (diff < 0) {
                borrow = 1
                result = String(diff + 10) + result
            } else {
                borrow = 0
                result = String(diff) + result
            }
        }
        result = removeLeadingZeros(result)
        if (cmp < 0) {
            result = "-" + result
        }
        return result
    }

    private static func compareAbs(num1: String, num2: String): Int {
        let num1Str = num1.replace("-", "").replace("+", "")
        let num2Str = num2.replace("-", "").replace("+", "")
        if (num1Str.length() != num2Str.length()) {
            return if (num1Str.length() > num2Str.length()) { 1 } else { -1 }
        }
        for (i in 0..num1Str.length() - 1) {
            if (num1Str[i] != num2Str[i]) {
                return if (num1Str[i] > num2Str[i]) { 1 } else { -1 }
            }
        }
        return 0
    }

    private static func removeLeadingZeros(s: String): String {
        for (i in 0..s.length() - 1) {
            if (s[i] != '0') {
                return s.substring(i)
            }
        }
        return "0"
    }

    public static func multiply(num1: String, num2: String): String {
        /*
        Multiplies two big numbers.
        :param num1: The first number to multiply,String.
        :param num2: The second number to multiply,String.
        :return: The product of the two numbers,String.
        >>> BigNumCalculator.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'

        */
        if (num1 == "0" || num2 == "0") {
            return "0"
        }
        let len1 = num1.length()
        let len2 = num2.length()
        var result = Array[Int](len1 + len2).fill(0)
        let sign = if ((num1.startsWith("-") && !num2.startsWith("-")) || (!num1.startsWith("-") && num2.startsWith("-"))) { -1 } else { 1 }
        let n1 = num1.replace("-", "")
        let n2 = num2.replace("-", "")
        for (i in 0..len1 - 1 where i < n1.length()) {
            for (j in 0..len2 - 1 where j < n2.length()) {
                let digit1 = n1[len1 - 1 - i].toDigit()
                let digit2 = n2[len2 - 1 - j].toDigit()
                let product = digit1 * digit2 + result[i + j]
                result[i + j] = product % 10
                result[i + j + 1] += product / 10
            }
        }
        var res = ""
        for (i in 0..result.length() - 1) {
            res = String(result[i]) + res
        }
        res = removeLeadingZeros(res)
        if (sign == -1 && res != "0") {
            res = "-" + res
        }
        return res
    }
}

