import std.collection.ArrayList

class BoyerMooreSearch {

    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        for (i in (this.patLen - 1)..0) {
            if (this.pattern[i] == char[0]) {
                return i
            }
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        for (i in 0..<this.patLen) {
            if (currentPos + i >= this.textLen) {
                return i
            }
            if (this.pattern[i] != this.text[currentPos + i]) {
                return i
            }
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        let result = ArrayList<Int64>()
        var s = Int64(0)
        while (s <= this.textLen - this.patLen) {
            var j = this.patLen - 1
            while (j >= 0 && this.pattern[j] == this.text[s + j]) {
                j -= 1
            }
            if (j < 0) {
                result.add(s)
                s += 1
            } else {
                let badCharShift = this.match_in_pattern(this.text[s + j].toString())
                if (badCharShift == -1) {
                    s += j + 1
                } else {
                    s += max(1, j - badCharShift)
                }
            }
        }
        return result
    }
}

