import std.time.DateTime
import std.collection.ArrayList

class Event <: Equatable<Event> {

    let date: DateTime
    let start_time: DateTime
    let end_time: DateTime
    let description: String

    public init(date: DateTime, start_time: DateTime, end_time: DateTime, description: String) {
        this.date = date
        this.start_time = start_time
        this.end_time = end_time
        this.description = description
    }

    public override operator func != (that: Event): Bool {
        return this.date != that.date || this.start_time != that.start_time || this.end_time != that.end_time || this.description != that.description
    }

    public override operator func == (that: Event): Bool {
        return this.date == that.date && this.start_time == that.start_time && this.end_time == that.end_time && this.description == that.description
    }
}

class CalendarUtil {

    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        this.events.add(event)
    }

    public func remove_event(event: Event): Unit {
        let index: Int64 = 0
        while index < this.events.size {
            if this.events[index] == event {
                this.events.remove(index)
                return
            }
            index += 1
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result: ArrayList<Event> = ArrayList<Event>()
        let index: Int64 = 0
        while index < this.events.size {
            let e: Event = this.events[index]
            if e.date.year == date.year && e.date.month == date.month && e.date.dayOfMonth == date.dayOfMonth {
                result.add(e)
            }
            index += 1
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        let index: Int64 = 0
        while index < this.events.size {
            let e: Event = this.events[index]
            if (start_time < e.end_time) && (e.start_time < end_time) {
                return false
            }
            index += 1
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let available: ArrayList<(DateTime, DateTime)> = ArrayList<(DateTime, DateTime)>()
        let day_events: ArrayList<Event> = this.get_events(date)

        // Sort events by start time
        day_events.sort(stable: true, comparator: (e1: Event, e2: Event) -> Ordering {
            if e1.start_time < e2.start_time {
                return Ordering.LT
            } else if e1.start_time > e2.start_time {
                return Ordering.GT
            } else {
                return Ordering.EQ
            }
        })

        let midnight: DateTime = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 0, minute: 0)
        let next_midnight: DateTime = midnight.plus(days: 1)

        var current_time: DateTime = midnight

        let index: Int64 = 0
        while index < day_events.size {
            let event: Event = day_events[index]
            if current_time < event.start_time {
                available.add((current_time, event.start_time))
            }
            if event.end_time > current_time {
                current_time = event.end_time
            }
            index += 1
        }

        if current_time < next_midnight {
            available.add((current_time, next_midnight))
        }

        return available
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now: DateTime = DateTime.now()
        let upcoming: ArrayList<Event> = ArrayList<Event>()
        let index: Int64 = 0
        while index < this.events.size {
            let event: Event = this.events[index]
            if event.start_time >= now {
                upcoming.add(event)
            }
            index += 1
        }

        upcoming.sort(stable: true, comparator: (e1: Event, e2: Event) -> Ordering {
            if e1.start_time < e2.start_time {
                return Ordering.LT
            } else if e1.start_time > e2.start_time {
                return Ordering.GT
            } else {
                return Ordering.EQ
            }
        })

        let result: ArrayList<Event> = ArrayList<Event>()
        let limit: Int64 = (num_events < upcoming.size) ? num_events : upcoming.size
        let i: Int64 = 0
        while i < limit {
            result.add(upcoming[i])
            i += 1
        }
        return result
    }
}

