import std.collection.ArrayList
import std.collection.HashMap

class ClassRegistrationSystem {

    var students: ArrayList<HashMap<String, String>>
    var students_registration_classes: HashMap<String, ArrayList<String>>

    public init() {
        this.students = ArrayList<HashMap<String, String>>()
        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        let name = student["name"]
        let major = student["major"]
        if name == null || major == null {
            return 0
        }
        for s in this.students {
            if s["name"] == name {
                return 0
            }
        }
        this.students.add(student)
        this.students_registration_classes.add(name, ArrayList<String>())
        return 1
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        let classes = this.students_registration_classes[student_name]
        if classes != null {
            if !classes.contains(class_name) {
                classes.add(class_name)
            }
            return classes
        } else {
            let new_classes = ArrayList<String>()
            new_classes.add(class_name)
            this.students_registration_classes.add(student_name, new_classes)
            return new_classes
        }
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        let result = ArrayList<String>()
        for student in this.students {
            if student["major"] == major {
                result.add(student["name"])
            }
        }
        return result
    }

    public func get_all_major(): ArrayList<String> {
        let majors = HashSet<String>()
        for student in this.students {
            let major = student["major"]
            if major != null {
                majors.add(major)
            }
        }
        return collectArrayList(majors)
    }

    public func get_most_popular_class_in_major(major: String): String {
        let class_count = HashMap<String, Int64>()
        let students_in_major = this.get_students_by_major(major)
        for student_name in students_in_major {
            let classes = this.students_registration_classes[student_name]
            if classes != null {
                for class_name in classes {
                    let count = class_count[class_name]
                    if count == null {
                        class_count.add(class_name, 1)
                    } else {
                        class_count.add(class_name, count + 1)
                    }
                }
            }
        }
        if class_count.size == 0 {
            return ""
        }
        let entries = class_count.entries()
        let first_entry = entries.first()
        var max_class = first_entry.key
        var max_count = first_entry.value
        for entry in entries {
            if entry.value > max_count {
                max_count = entry.value
                max_class = entry.key
            }
        }
        return max_class
    }
}

