class CSVProcessor {

    /*
    This is a class for processing CSV files, including readring and writing CSV data, as well as processing specific operations and saving as a new CSV file.
    */

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = File(file_name)
        let input = file.openRead()
        let content = input.readToEnd().getOrThrow()
        input.close()

        let lines = content.split("\n")
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()

        if lines.size() == 0 {
            return (title, data)
        }

        let titleParts = lines[0].split(",")
        for part in titleParts {
            title.add(part.trim())
        }

        for i in Range(1, lines.size()) {
            let line = lines[i].trim()
            if line == "" {
                continue
            }
            let parts = line.split(",")
            let row = ArrayList<String>()
            for part in parts {
                row.add(part.trim())
            }
            data.add(row)
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = File(file_name)
        let output = file.openWrite()

        for row in data {
            let line = ""
            for i in Range(0, row.size()) {
                if i > 0 {
                    line += ","
                }
                line += row[i]
            }
            output.write(line.toBytes())
            output.write("\n".toBytes())
        }

        output.flush()
        output.close()

        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)
        if data.size() == 0 && title.size() <= N {
            return 0
        }

        let processedData = ArrayList<ArrayList<String>>()
        let newRow = ArrayList<String>()

        for row in data {
            if N < row.size() {
                let value = row[N.toInt()].toUpperCase()
                newRow.add(value)
            }
        }
        processedData.add(newRow)

        let newName = save_file_name.substring(0, save_file_name.lastIndexOf(".")) + "_process" + save_file_name.substring(save_file_name.lastIndexOf("."))

        let allData = ArrayList<ArrayList<String>>()
        allData.add(title)
        for row in processedData {
            allData.add(row)
        }

        let result = write_csv(allData, newName)
        return result
    }
}

