    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var sum: Float64 = 0.0
        for i in 0..data.size() {
            sum = sum + data.get(i)
        }
        return sum
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        var min: Float64 = data.get(0)
        for i in 1..data.size() {
            if data.get(i) < min {
                min = data.get(i)
            }
        }
        return min
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        var max: Float64 = data.get(0)
        for i in 1..data.size() {
            if data.get(i) > max {
                max = data.get(i)
            }
        }
        return max
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        let mean: Float64 = this.get_sum() / data.size()
        var variance: Float64 = 0.0
        for i in 0..data.size() {
            let diff: Float64 = data.get(i) - mean
            variance = variance + (diff * diff)
        }
        variance = variance / data.size()
        return round(variance * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        let variance: Float64 = this.get_variance()
        let std_dev: Float64 = sqrt(variance)
        return round(std_dev * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        if data.size() <= 1 {
            return 1.0
        }
        let n: Int32 = data.size()
        var sum_x: Float64 = 0.0
        var sum_y: Float64 = 0.0
        var sum_xy: Float64 = 0.0
        var sum_x2: Float64 = 0.0
        var sum_y2: Float64 = 0.0

        for i in 0..n {
            let x: Float64 = i + 1.0
            let y: Float64 = data.get(i)
            sum_x = sum_x + x
            sum_y = sum_y + y
            sum_xy = sum_xy + (x * y)
            sum_x2 = sum_x2 + (x * x)
            sum_y2 = sum_y2 + (y * y)
        }

        let numerator: Float64 = n * sum_xy - sum_x * sum_y
        let denominator: Float64 = sqrt(n * sum_x2 - sum_x * sum_x) * sqrt(n * sum_y2 - sum_y * sum_y)

        if abs(denominator) < 1e-9 {
            return 0.0
        }

        let corr: Float64 = numerator / denominator
        return round(corr * 100.0) / 100.0
    }
}
