import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size()
        if n == 0 || n != data2.size() {
            return 0.0
        }

        let mean1 = data1.reduce(0.0, func(acc: Float64, x: Float64): Float64 { acc + x }) / n
        let mean2 = data2.reduce(0.0, func(acc: Float64, x: Float64): Float64 { acc + x }) / n

        let cov = data1.zip(data2).reduce(0.0, func(acc: Float64, pair: (Float64, Float64)): Float64 {
            let (x, y) = pair
            return acc + (x - mean1) * (y - mean2)
        }) / n

        let var1 = data1.reduce(0.0, func(acc: Float64, x: Float64): Float64 {
            return acc + (x - mean1) * (x - mean1)
        }) / n

        let var2 = data2.reduce(0.0, func(acc: Float64, x: Float64): Float64 {
            return acc + (x - mean2) * (x - mean2)
        }) / n

        if var1 == 0.0 || var2 == 0.0 {
            return 0.0
        }

        return cov / sqrt(var1 * var2)
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        if n == 0 {
            return 0.0
        }

        let mean = data.reduce(0.0, func(acc: Float64, x: Float64): Float64 { acc + x }) / n

        let m2 = data.reduce(0.0, func(acc: Float64, x: Float64): Float64 {
            let diff = x - mean
            return acc + diff * diff
        }) / n

        let m3 = data.reduce(0.0, func(acc: Float64, x: Float64): Float64 {
            let diff = x - mean
            return acc + diff * diff * diff
        }) / n

        if m2 == 0.0 {
            return 0.0
        }

        let std_dev = sqrt(m2)
        return m3 / (std_dev * std_dev * std_dev)
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        if n == 0 {
            return 0.0
        }

        let mean = data.reduce(0.0, func(acc: Float64, x: Float64): Float64 { acc + x }) / n

        let m2 = data.reduce(0.0, func(acc: Float64, x: Float64): Float64 {
            let diff = x - mean
            return acc + diff * diff
        }) / n

        let m4 = data.reduce(0.0, func(acc: Float64, x: Float64): Float64 {
            let diff = x - mean
            let diff2 = diff * diff
            return acc + diff2 * diff2
        }) / n

        if m2 == 0.0 {
            return 0.0
        }

        return m4 / (m2 * m2) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let norm = 1.0 / (sqrt(2.0 * 3.141592653589793) * sigma)

        for x in data {
            let exponent = -0.5 * ((x - mu) / sigma) * ((x - mu) / sigma)
            let value = norm * exp(exponent)
            result.add(value)
        }

        return result
    }
}

