import std.collection.ArrayList

class DecryptionUtils {

    /*
    This is a class that provides methods for decryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,String.
        */
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        /*
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,String.
        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'

        */
        let result: ArrayList<Char> = ArrayList<Char>()
        for char in ciphertext.toCharArray() {
            if char >= 'a' && char <= 'z' {
                let shifted = (((char - 'a') - shift + 26) % 26) + 'a'
                result.add(shifted as Char)
            } else if char >= 'A' && char <= 'Z' {
                let shifted = (((char - 'A') - shift + 26) % 26) + 'A'
                result.add(shifted as Char)
            } else {
                result.add(char)
            }
        }
        return String.fromCharArray(result.toArray())
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'

        */
        if key.isEmpty() {
            return ciphertext
        }
        let result: ArrayList<Char> = ArrayList<Char>()
        let keyChars = key.toLowerCase().toCharArray()
        let ciphertextChars = ciphertext.toCharArray()
        var keyIndex = 0
        for char in ciphertextChars {
            if char >= 'a' && char <= 'z' {
                let keyChar = keyChars[keyIndex % keyChars.size]
                let shift = keyChar - 'a'
                let decrypted = ((char - 'a' - shift + 26) % 26) + 'a'
                result.add(decrypted as Char)
                keyIndex += 1
            } else if char >= 'A' && char <= 'Z' {
                let keyChar = keyChars[keyIndex % keyChars.size]
                let shift = keyChar - 'a'
                let decrypted = ((char - 'A' - shift + 26) % 26) + 'A'
                result.add(decrypted as Char)
                keyIndex += 1
            } else {
                result.add(char)
            }
        }
        return String.fromCharArray(result.toArray())
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'

        */
        if rails <= 1 || encrypted_text.isEmpty() {
            return encrypted_text
        }
        let n = encrypted_text.size
        let matrix: ArrayList<ArrayList<Char?>> = ArrayList<ArrayList<Char?>>()
        for _ in 0..rails {
            matrix.add(ArrayList<Char?>())
        }
        var rail = 0
        var direction = -1
        for i in 0..n {
            for j in 0..rails {
                matrix[j].add(null)
            }
            if rail == 0 || rail == rails - 1 {
                direction = -direction
            }
            matrix[rail][i] = '*'
            rail += direction
        }
        var index = 0
        for row in matrix {
            for cellIndex in 0..row.size {
                if row[cellIndex] == '*' {
                    row[cellIndex] = encrypted_text[index] as Char?
                    index += 1
                }
            }
        }
        let result: ArrayList<Char> = ArrayList<Char>()
        rail = 0
        direction = -1
        for i in 0..n {
            result.add(matrix[rail][i]!! as Char)
            if rail == 0 || rail == rails - 1 {
                direction = -direction
            }
            rail += direction
        }
        return String.fromCharArray(result.toArray())
    }
}

