        >>> e.caesar_cipher("abc", 1)
        'bcd'

        */
        let chars = plaintext.toCharArray()
        let result = ArrayList<Char>()
        for char in chars {
            if char >= 'a' && char <= 'z' {
                let shifted = (char - 'a' + shift) % 26 + 'a'
                result.append(shifted as Char)
            } else if char >= 'A' && char <= 'Z' {
                let shifted = (char - 'A' + shift) % 26 + 'A'
                result.append(shifted as Char)
            } else {
                result.append(char)
            }
        }
        return result.toArray().toString()
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'

        */
        let text_chars = plain_text.toCharArray()
        let key_chars = this.key.toCharArray()
        let key_len = key_chars.length
        let result = ArrayList<Char>()
        for i in 0..text_chars.length {
            let char = text_chars[i]
            if char >= 'a' && char <= 'z' {
                let key_char = key_chars[i % key_len]
                let k = (key_char >= 'a' && key_char <= 'z') ? key_char - 'a' : key_char - 'A'
                let shifted = (char - 'a' + k) % 26 + 'a'
                result.append(shifted as Char)
            } else if char >= 'A' && char <= 'Z' {
                let key_char = key_chars[i % key_len]
                let k = (key_char >= 'a' && key_char <= 'z') ? key_char - 'a' : key_char - 'A'
                let shifted = (char - 'A' + k) % 26 + 'A'
                result.append(shifted as Char)
            } else {
                result.append(char)
            }
        }
        return result.toArray().toString()
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'

        */
        if rails <= 1 {
            return plain_text
        }
        let n = plain_text.length()
        let text_chars = plain_text.toCharArray()
        let matrix = ArrayList<ArrayList<Char>>()
        for i in 0..rails {
            matrix.append(ArrayList<Char>())
        }
        let down = true
        var row = 0
        for i in 0..n {
            matrix[row].append(text_chars[i])
            if row == 0 {
                down = true
            } else if row == rails - 1 {
                down = false
            }
            if down {
                row += 1
            } else {
                row -= 1
            }
        }
        let result = ArrayList<Char>()
        for i in 0..rails {
            let row_chars = matrix[i].toArray()
            for c in row_chars {
                result.append(c)
            }
        }
        return result.toArray().toString()
    }
}
