import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        prepare(expression)
        var value_stack = ArrayList<Decimal>()
        for token in postfix_stack {
            if Regex("^[+]?-?\\d+\\.?\\d*$").matches(token) {
                value_stack.add(Decimal(token))
            } else if ExpressionCalculator.is_operator(token) {
                let second = value_stack.removeAt(value_stack.size() - 1)
                let first = value_stack.removeAt(value_stack.size() - 1)
                let result = ExpressionCalculator._calculate(first, second, token)
                value_stack.add(result)
            }
        }
        return value_stack.get(0).toFloat64()
    }

    public func prepare(expression: String): Unit {
        let real_expr = ExpressionCalculator.transform(expression)
        var oper_stack = ArrayList<String>()
        var num = ""
        for i in 0..real_expr.length() {
            let c = real_expr.substring(i, i + 1)
            if Regex("\\d").matches(c) || c == "." {
                num += c
            } else {
                if num != "" {
                    postfix_stack.add(num)
                    num = ""
                }
                if c == "(" {
                    oper_stack.add(c)
                } else if c == ")" {
                    while !oper_stack.isEmpty() && oper_stack.get(oper_stack.size() - 1) != "(" {
                        postfix_stack.add(oper_stack.removeAt(oper_stack.size() - 1))
                    }
                    oper_stack.removeAt(oper_stack.size() - 1)
                } else if ExpressionCalculator.is_operator(c) {
                    while !oper_stack.isEmpty() 
                        && oper_stack.get(oper_stack.size() - 1) != "(" 
                        && compare(c, oper_stack.get(oper_stack.size() - 1)) {
                        postfix_stack.add(oper_stack.removeAt(oper_stack.size() - 1))
                    }
                    oper_stack.add(c)
                }
            }
        }
        if num != "" {
            postfix_stack.add(num)
        }
        while !oper_stack.isEmpty() {
            postfix_stack.add(oper_stack.removeAt(oper_stack.size() - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        return c == "+" || c == "-" || c == "*" || c == "/" || c == "%" || c == "(" || c == ")"
    }

    public func compare(cur: String, peek: String): Bool {
        let cur_index = 0
        let peek_index = 0
        match (cur) {
            "+" => cur_index = 1,
            "-" => cur_index = 2,
            "*" => cur_index = 3,
            "/" => cur_index = 4,
            "%" => cur_index = 5,
            "(" => cur_index = 6,
            ")" => cur_index = 7,
            _ => cur_index = 0
        }
        match (peek) {
            "+" => peek_index = 1,
            "-" => peek_index = 2,
            "*" => peek_index = 3,
            "/" => peek_index = 4,
            "%" => peek_index = 5,
            "(" => peek_index = 6,
            ")" => peek_index = 7,
            _ => peek_index = 0
        }
        return operat_priority.get(cur_index) >= operat_priority.get(peek_index)
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            "+" => return first_value + second_value,
            "-" => return first_value - second_value,
            "*" => return first_value * second_value,
            "/" => return first_value / second_value,
            "%" => return first_value % second_value,
            _ => return Decimal("0")
        }
    }

    public static func transform(expression: String): String {
        return expression.replace(" ", "")
    }
}

