import std.collection.ArrayList

class GomokuGame {

    let board_size: Int64
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(board_size: Int64) {
        this.board_size = board_size
        this.board = ArrayList<ArrayList<String>>()
        this.current_player = "X"
        for (_ in 0..board_size) {
            let row: ArrayList<String> = ArrayList<String>()
            for (_ in 0..board_size) {
                row.add(" ")
            }
            board.add(row)
        }
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (row < 0 || row >= board_size || col < 0 || col >= board_size) {
            return false
        }
        let target_row = board.at(row)
        if (target_row.at(col) != " ") {
            return false
        }
        target_row.set(col, current_player)
        current_player = if (current_player == "X") "O" else "X"
        return true
    }

    public func check_winner(): Option<String> {
        let directions: ArrayList<(Int64, Int64)> = ArrayList.of([(0, 1), (1, 0), (1, 1), (1, -1)])
        for (i in 0..board_size) {
            for (j in 0..board_size) {
                let symbol = board.at(i).at(j)
                if (symbol == " ") {
                    continue
                }
                for (dir in directions) {
                    if (_check_five_in_a_row(i, j, dir)) {
                        return Some(symbol)
                    }
                }
            }
        }
        return None
    }

    public func _check_five_in_a_row(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        let (dx, dy) = direction
        let player = board.at(row).at(col)
        if (player == " ") {
            return false
        }
        for (i in 0..5) {
            let r = row + i * dx
            let c = col + i * dy
            if (r < 0 || r >= board_size || c < 0 || c >= board_size || board.at(r).at(c) != player) {
                return false
            }
        }
        return true
    }
}

