import std.collection.HashMap

class Hotel {

    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        if !available_rooms.containsKey(room_type) {
            return "false"
        }
        let available = available_rooms[room_type]
        if room_number <= 0 {
            return "false"
        }
        if room_number <= available {
            available_rooms[room_type] = available - room_number
            if !booked_rooms.containsKey(room_type) {
                booked_rooms[room_type] = HashMap<String, Int64>()
            }
            let current_booked = booked_rooms[room_type].get(name).getOrElse(0)
            booked_rooms[room_type][name] = current_booked + room_number
            return "Success!"
        } else {
            if available > 0 {
                return available.toString()
            } else {
                return "false"
            }
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        if !booked_rooms.containsKey(room_type) {
            return false
        }
        let room_map = booked_rooms[room_type]
        if !room_map.containsKey(name) {
            return false
        }
        let booked = room_map[name]
        if room_number > booked {
            return false
        }
        if room_number == booked {
            room_map.remove(name)
        } else {
            room_map[name] = booked - room_number
        }
        if room_map.isEmpty() {
            booked_rooms.remove(room_type)
        }
        return true
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        let current = available_rooms.get(room_type).getOrElse(0)
        available_rooms[room_type] = current + room_number
    }

    public func get_available_rooms(room_type: String): Int64 {
        return available_rooms.get(room_type).getOrElse(0)
    }
}

