import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for xi in x_interp {
            let n = x.size()
            var left = 0
            var right = n - 1
            if xi <= x[left] {
                result.append(y[left])
            } else if xi >= x[right] {
                result.append(y[right])
            } else {
                while right - left > 1 {
                    let mid = (left + right) / 2
                    if x[mid] <= xi {
                        left = mid
                    } else {
                        right = mid
                    }
                }
                let x0 = x[left]
                let x1 = x[right]
                let y0 = y[left]
                let y1 = y[right]
                let yi = y0 + (xi - x0) * (y1 - y0) / (x1 - x0)
                result.append(yi)
            }
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for i in 0..x_interp.size() {
            let xi = x_interp[i]
            let yi = y_interp[i]
            let nx = x.size()
            let ny = y.size()
            var x_left = 0
            var x_right = nx - 1
            var y_left = 0
            var y_right = ny - 1

            if xi <= x[x_left] {
                x_left = 0
                x_right = 1
            } else if xi >= x[x_right] {
                x_left = nx - 2
                x_right = nx - 1
            } else {
                while x_right - x_left > 1 {
                    let mid = (x_left + x_right) / 2
                    if x[mid] <= xi {
                        x_left = mid
                    } else {
                        x_right = mid
                    }
                }
            }

            if yi <= y[y_left] {
                y_left = 0
                y_right = 1
            } else if yi >= y[y_right] {
                y_left = ny - 2
                y_right = ny - 1
            } else {
                while y_right - y_left > 1 {
                    let mid = (y_left + y_right) / 2
                    if y[mid] <= yi {
                        y_left = mid
                    } else {
                        y_right = mid
                    }
                }
            }

            let x0 = x[x_left]
            let x1 = x[x_right]
            let y0 = y[y_left]
            let y1 = y[y_right]

            let q11 = z[x_left][y_left]
            let q21 = z[x_right][y_left]
            let q12 = z[x_left][y_right]
            let q22 = z[x_right][y_right]

            let x_diff = x1 - x0
            let y_diff = y1 - y0

            let f_x_y0 = (x1 - xi) * q11 / x_diff + (xi - x0) * q21 / x_diff
            let f_x_y1 = (x1 - xi) * q12 / x_diff + (xi - x0) * q22 / x_diff

            let zi = (y1 - yi) * f_x_y0 / y_diff + (yi - y0) * f_x_y1 / y_diff

            result.append(zi)
        }
        return result
    }
}

