class IpUtil {

    /*
    This is a class as tool for ip that can be used to obtain the local IP address, validate its validity, and also provides the functionality to retrieve the corresponding hostname.
    */

    public static func is_valid_ipv4(ip_address: String): Bool {
        match IPAddress.tryParse(ip_address) {
            case Some(addr) => addr.isIPv4()
            case None => false
        }
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        match IPAddress.tryParse(ip_address) {
            case Some(addr) => addr.isIPv6()
            case None => false
        }
    }

    public static func get_hostname(ip_address: String): Option<String> {
        let addr = IPAddress.tryParse(ip_address)
        if addr.isNone() {
            return None
        }
        // Note: hostName property is not yet implemented according to the docs
        // So we cannot actually resolve hostname from IP in current environment
        // Returning None to reflect unimplemented behavior
        return None
    }
}

