import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        // Calculate observed agreement (Po)
        var Po: Float64 = 0.0
        for i in Range(0, k) {
            var sum: Int64 = 0
            for j in Range(0, k) {
                sum += testData[i][j]
            }
            if sum > 0 {
                Po += (testData[i][i].toFloat64()) / sum.toFloat64()
            }
        }
        Po /= k.toFloat64()

        // Calculate expected agreement (Pe)
        var Pe: Float64 = 0.0
        var total: Int64 = 0
        for i in Range(0, k) {
            for j in Range(0, k) {
                total += testData[i][j]
            }
        }

        for j in Range(0, k) {
            var colSum: Int64 = 0
            for i in Range(0, k) {
                colSum += testData[i][j]
            }
            Pe += (colSum.toFloat64() / total.toFloat64()) * (colSum.toFloat64() / total.toFloat64())
        }

        // Calculate kappa
        if abs(1.0 - Pe) < 1e-9 {
            return 0.0
        }
        return (Po - Pe) / (1.0 - Pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var totalRatings: Int64 = 0
        for i in Range(0, N) {
            for j in Range(0, k) {
                totalRatings += testData[i][j]
            }
        }

        // Calculate P_bar (mean of observed agreement)
        var P_bar: Float64 = 0.0
        for i in Range(0, N) {
            var Pi: Float64 = 0.0
            for j in Range(0, k) {
                Pi += (testData[i][j].toFloat64() * testData[i][j].toFloat64())
            }
            Pi -= n.toFloat64()
            Pi /= (n.toFloat64() * (n.toFloat64() - 1.0))
            P_bar += Pi
        }
        P_bar /= N.toFloat64()

        // Calculate P_e_bar (expected agreement by chance)
        var P_e_bar: Float64 = 0.0
        for j in Range(0, k) {
            var pj: Float64 = 0.0
            for i in Range(0, N) {
                pj += testData[i][j].toFloat64()
            }
            pj /= (n.toFloat64() * N.toFloat64())
            P_e_bar += (pj * pj)
        }

        // Calculate Fleiss' Kappa
        if abs(1.0 - P_e_bar) < 1e-9 {
            return 0.0
        }
        return (P_bar - P_e_bar) / (1.0 - P_e_bar)
    }
}

