        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        */
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let board = ArrayList<ArrayList<String>>(rows)
        let rng = Random(0)
        for (i in 0..rows) {
            let row = ArrayList<String>(cols)
            for (j in 0..cols) {
                let icon = ICONS[rng.nextInt64() % ICONS.size()]
                row.add(icon)
            }
            board.add(row)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
