        let (x1, y1) = pos1
        let (x2, y2) = pos2
        if (x1 < 0 || x1 >= BOARD_SIZE[0] || y1 < 0 || y1 >= BOARD_SIZE[1] ||
            x2 < 0 || x2 >= BOARD_SIZE[0] || y2 < 0 || y2 >= BOARD_SIZE[1]) {
            return false
        }
        if (pos1 == pos2) {
            return false
        }
        if (board[x1][y1] != board[x2][y2]) {
            return false
        }
        if (board[x1][y1] == " ") {
