class Manacher {

    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        if center - diff < 0 || center + diff >= string.size() {
            return 0
        }
        if string.get(center - diff) != string.get(center + diff) {
            return 0
        }
        return 1 + palindromic_length(center, diff + 1, string)
    }

    public func palindromic_string(): String {
        if input_string.isEmpty() {
            return ""
        }
        var temp_string: String = ""
        for i in 0..input_string.size() {
            temp_string += input_string.get(i)
            if i != input_string.size() - 1 {
                temp_string += "|"
            }
        }
        var max_length: Int64 = 0
        var start: Int64 = 0
        for i in 0..temp_string.size() {
            var current_length: Int64 = palindromic_length(i, 1, temp_string)
            if current_length > max_length {
                max_length = current_length
                start = i - current_length
            }
        }
        var longest_palindrome: String = ""
        for i in start..(start + 2 * max_length + 1) {
            if temp_string.get(i) != '|' {
                longest_palindrome += temp_string.get(i)
            }
        }
        return longest_palindrome
    }
}

