import std.collection.ArrayList
import std.math.abs

class MetricsCalculator2 {

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        let results = ArrayList<Float64>()

        if data is (ArrayList<Int64>, Int64) {
            let (ranks, total) = data as (ArrayList<Int64>, Int64)
            let reciprocal = calculateReciprocalRank(ranks)
            results.add(reciprocal)
        } else if data is ArrayList<(ArrayList<Int64>, Int64)> {
            let dataList = data as ArrayList<(ArrayList<Int64>, Int64)>
            for item in dataList {
                let (ranks, total) = item
                let reciprocal = calculateReciprocalRank(ranks)
                results.add(reciprocal)
            }
        }

        let avg = results.iter().sum() / results.size() as Float64
        return (avg, results)
    }

    private static func calculateReciprocalRank(ranks: ArrayList<Int64>): Float64 {
        for i in 0..ranks.size() {
            if ranks[i] == 1 {
                return 1.0 / ((i + 1) as Float64)
            }
        }
        return 0.0
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        let results = ArrayList<Float64>()

        if data is (ArrayList<Int64>, Int64) {
            let (ranks, total) = data as (ArrayList<Int64>, Int64)
            let ap = calculateAveragePrecision(ranks, total)
            results.add(ap)
        } else if data is ArrayList<(ArrayList<Int64>, Int64)> {
            let dataList = data as ArrayList<(ArrayList<Int64>, Int64)>
            for item in dataList {
                let (ranks, total) = item
                let ap = calculateAveragePrecision(ranks, total)
                results.add(ap)
            }
        }

        let avg = results.iter().sum() / results.size() as Float64
        return (avg, results)
    }

    private static func calculateAveragePrecision(ranks: ArrayList<Int64>, total: Int64): Float64 {
        var correctCount = 0
        var totalPrecision = 0.0
        for i in 0..ranks.size() {
            if ranks[i] == 1 {
                correctCount += 1
                totalPrecision += (correctCount as Float64) / ((i + 1) as Float64)
            }
        }
        if correctCount == 0 {
            return 0.0
        }
        return totalPrecision / (total as Float64)
    }
}

