import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        var words_list = ArrayList<ArrayList<String>>()
        var pattern = Regex("[^a-zA-Z\\s]")

        for str in string_list {
            var cleaned = pattern.replace_all(str, "")
            cleaned = cleaned.to_lower()
            var words = cleaned.split("\\s+").filter({ w: String => return w.length() > 0 })
            words_list.append(ArrayList<String>(words))
        }

        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        var freq_map = HashMap<String, Int64>()

        for words in words_list {
            for word in words {
                if (freq_map.contains(word)) {
                    freq_map[word] = freq_map[word] + 1
                } else {
                    freq_map[word] = 1
                }
            }
        }

        var sorted_entries = ArrayList<HashMap.Entry<String, Int64>>(freq_map.entries())
        sort<HashMap.Entry<String, Int64>, Int64>(
            sorted_entries,
            key: { entry: HashMap.Entry<String, Int64> => return entry.value },
            descending: true
        )

        var result = HashMap<String, Int64>()
        var count = 0
        for entry in sorted_entries {
            if (count >= 5) {
                break
            }
            result[entry.key] = entry.value
            count = count + 1
        }

        return result
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        var words_list = this.process_data(string_list)
        return this.calculate_word_frequency(words_list)
    }
}

