import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    /*
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    */

    public init() {}

    public func replace(string: String): String {
        var result = StringBuilder()
        var i = 0
        let len = string.length()

        while i < len {
            let char = string[i]
            if char == r'&' && i + 1 < len && string[i + 1] == r'#' {
                var j = i + 2
                var is_hex = false
                if j < len && (string[j] == r'x' || string[j] == r'X') {
                    is_hex = true
                    j += 1
                }

                if j < len {
                    var value = 0
                    var parsed = false
                    var k = j

                    while k < len && ((is_hex && NumericEntityUnescaper.is_hex_char(string[k])) || 
                                      (!is_hex && char.is_digit()))) {
                        k += 1
                    }

                    if k > j && k < len && string[k] == r';' {
                        let numStr = string.substring(j, k - j)
                        let radix = if is_hex then 16 else 10
                        let optValue = Int32.tryParse(numStr, radix)
                        if optValue.is_some() {
                            value = optValue.unwrap()
                            result.append(Rune(value))
                            i = k + 1
                            parsed = true
                        }
                    }

                    if !parsed {
                        result.append(char)
                        i += 1
                    }
                } else {
                    result.append(char)
                    i += 1
                }
            } else {
                result.append(char)
                i += 1
            }
        }

        return result.to_string()
    }

    public static func is_hex_char(char: Rune): Bool {
        return char.is_digit() || (char >= r'a' && char <= r'f') || (char >= r'A' && char <= r'F')
    }
}

