import std.collection.ArrayList
import std.collection.HashMap

class Dish <: Equatable<Dish> {

    let dish: String
    let price: Int64
    var count: Int64

    public init(dish: String, price: Int64, count: Int64) {
        this.dish = dish
        this.price = price
        this.count = count
    }

    public override operator func != (that: Dish): Bool {
        return this.dish != that.dish || this.price != that.price || this.count != that.count
    }

    public override operator func == (that: Dish): Bool {
        return this.dish == that.dish && this.price == that.price && this.count == that.count
    }
}

class Order {

    let menu: ArrayList<Dish>
    let selected_dishes: ArrayList<Dish>
    let sales: HashMap<String, Float64>

    public init() {
        this.menu = ArrayList<Dish>()
        this.selected_dishes = ArrayList<Dish>()
        this.sales = HashMap<String, Float64>()
    }

    public func add_dish(dish: Dish): Bool {
        for (i in 0..this.menu.size()) {
            var menu_dish = this.menu[i]
            if (menu_dish.dish == dish.dish && menu_dish.price == dish.price) {
                if (menu_dish.count >= dish.count) {
                    menu_dish.count = menu_dish.count - dish.count
                    this.selected_dishes.add(Dish(dish.dish, dish.price, dish.count))
                    return true
                } else {
                    return false
                }
            }
        }
        return false
    }

    public func calculate_total(): Float64 {
        var total: Float64 = 0.0
        for (selected in this.selected_dishes) {
            var dish_name = selected.dish
            var price = selected.price.toFloat64()
            var count = selected.count.toFloat64()
            var sale: Float64 = 1.0
            if (this.sales.contains(dish_name)) {
                sale = this.sales[dish_name]
            }
            total = total + (price * count * sale)
        }
        return total
    }

    public func checkout(): Option<Float64> {
        if (this.selected_dishes.size() == 0) {
            return None<Float64>
        } else {
            var total = this.calculate_total()
            this.selected_dishes.clear()
            return Some(total)
        }
    }
}

