import std.collection.ArrayList

class PushBoxGame {

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for row in Int64(0)..<map.getSize() {
                let current_row = map.get(row)!!
                for col in Int64(0)..<current_row.getSize() {
                    let cell = current_row.get(col)!!
                    if cell == "O" {
                        this.player_row = row
                        this.player_col = col
                    } else if cell == "G" {
                        let target_pos = ArrayList<Int64>()
                        target_pos.add(row)
                        target_pos.add(col)
                        this.targets.add(target_pos)
                        this.target_count += 1
                    } else if cell == "X" {
                        let box_pos = ArrayList<Int64>()
                        box_pos.add(row)
                        box_pos.add(col)
                        this.boxes.add(box_pos)
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var completed = Int64(0)
        for box in boxes {
            let box_row = box.get(0)!!
            let box_col = box.get(1)!!
            for target in targets {
                let target_row = target.get(0)!!
                let target_col = target.get(1)!!
                if box_row == target_row && box_col == target_col {
                    completed += 1
                    break
                }
            }
        }
        this.is_game_over = (completed == target_count)
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        let row_dirs = HashMap<String, Int64>()
        row_dirs.put("w", -1)
        row_dirs.put("s", 1)
        row_dirs.put("a", 0)
        row_dirs.put("d", 0)
        let col_dirs = HashMap<String, Int64>()
        col_dirs.put("w", 0)
        col_dirs.put("s", 0)
        col_dirs.put("a", -1)
        col_dirs.put("d", 1)

        if !row_dirs.containsKey(direction) {
            return check_win()
        }

        let dr = row_dirs.get(direction)!!
        let dc = col_dirs.get(direction)!!
        let new_row = player_row + dr
        let new_col = player_col + dc
        let next_row = new_row + dr
        let next_col = new_col + dc

        if new_row < 0 || new_row >= map.getSize() || new_col < 0 || new_col >= map.get(new_row)!!.getSize() {
            return check_win()
        }

        let target_cell = map.get(new_row)!!.get(new_col)!!
        if target_cell == "#" {
            return check_win()
        }

        var box_moved = false
        for box in boxes {
            let box_row = box.get(0)!!
            let box_col = box.get(1)!!
            if box_row == new_row && box_col == new_col {
                if next_row < 0 || next_row >= map.getSize() || next_col < 0 || next_col >= map.get(next_row)!!.getSize() {
                    return check_win()
                }
                let next_cell = map.get(next_row)!!.get(next_col)!!
                if next_cell == "#" {
                    return check_win()
                }
                for other_box in boxes {
                    let other_row = other_box.get(0)!!
                    let other_col = other_box.get(1)!!
                    if other_row == next_row && other_col == next_col {
                        return check_win()
                    }
                }
                box.set(0, next_row)
                box.set(1, next_col)
                box_moved = true
                break
            }
        }

        player_row = new_row
        player_col = new_col
        return check_win()
    }
}

