import std.collection.ArrayList
import std.random.Random

class Snake {

    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let head_x: Int64 = this.positions[0][0] + direction[0]
        let head_y: Int64 = this.positions[0][1] + direction[1]
        let new_head: ArrayList<Int64> = ArrayList<Int64>([head_x, head_y])

        if head_x == this.food_position[0] && head_y == this.food_position[1] {
            this.positions = ArrayList<ArrayList<Int64>>([new_head] + this.positions.toArray())
            this.eat_food()
        } else {
            let tail: Int64 = this.positions.size() - 1
            this.positions = this.positions[Range<Int64>(0, tail)] ++ ArrayList<ArrayList<Int64>>([new_head])
            for pos in this.positions[Range<Int64>(0, this.positions.size() - 1)].toArray() {
                if pos[0] == head_x && pos[1] == head_y {
                    this.reset()
                    return
                }
            }
        }
    }

    public func random_food_position(): Unit {
        let random: Random = Random()
        while true {
            let x: Int64 = random.nextInt() % (this.SCREEN_WIDTH / this.BLOCK_SIZE) * this.BLOCK_SIZE
            let y: Int64 = random.nextInt() % (this.SCREEN_HEIGHT / this.BLOCK_SIZE) * this.BLOCK_SIZE
            let candidate: ArrayList<Int64> = ArrayList<Int64>([x, y])
            var on_snake: Bool = false
            for pos in this.positions.toArray() {
                if pos[0] == x && pos[1] == y {
                    on_snake = true
                    break
                }
            }
            if !on_snake {
                this.food_position = candidate
                break
            }
        }
    }

    public func reset(): Unit {
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        this.length += 1
        this.score += 100
        this.random_food_position()
    }
}

