import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let regex = Regex(#"(?<!Mr)\.\s+|\?\s+"#)
        let parts = regex.split(sentences_string.trim())
        let result = ArrayList<String>()
        var lastIndex = 0
        for (i in 0..parts.size()) {
            let part = parts[i]
            if (part != "") {
                let start = (i == 0) ? 0 : sentences_string.indexOf(part, lastIndex)
                let end = start + part.size()
                if (i > 0 && sentences_string.get(end - 1) == ' ') {
                    end = end - 1
                }
                if (i < parts.size() - 1) {
                    let nextPart = parts[i + 1]
                    let nextStart = sentences_string.indexOf(nextPart, end)
                    result.add(sentences_string.substring(start, nextStart).trim())
                    lastIndex = nextStart
                } else {
                    result.add(sentences_string.substring(start).trim())
                }
            }
        }
        return result
    }

    public func count_words(sentence: String): Int64 {
        let cleaned = sentence.replaceAll(#[^a-zA-Z\s]#, "")
        let words = cleaned.split(" ", removeEmpty: true)
        return words.size()
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = split_sentences(sentences_string)
        var maxCount = 0i64
        for (sentence in sentences) {
            let wordCount = count_words(sentence)
            if (wordCount > maxCount) {
                maxCount = wordCount
            }
        }
        return maxCount
    }
}

