import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let sorted = data.clone()
        sort(sorted, (a: Int64, b: Int64) => a < b)
        let n = sorted.size()
        if n == 0 {
            return 0.0
        }
        if n % 2 == 1 {
            return sorted.get((n - 1) / 2) as Float64
        } else {
            let mid1 = sorted.get(n / 2 - 1)
            let mid2 = sorted.get(n / 2)
            return (mid1 + mid2) as Float64 / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int32>()
        for val in data {
            freq.put(val, freq.get(val).orDefault(0) + 1)
        }
        var maxCount = 0
        for count in freq.values() {
            if count > maxCount {
                maxCount = count
            }
        }
        let modes = ArrayList<Int64>()
        for (val, count) in freq {
            if count == maxCount {
                modes.add(val)
            }
        }
        sort(modes, (a: Int64, b: Int64) => a < b)
        return modes
    }

