import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    /*
    The class allows to calculate trigonometric values, including cosine, sine, and tangent, using Taylor series approximations.
    */

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        let rad = x * PI / 180.0
        return taylor(rad, 50)
    }

    public func factorial(a: Int64): Decimal {
        if a < 0 {
            panic("Factorial is not defined for negative numbers")
        }
        var result = Decimal(1)
        for i in 1..a {
            result = result * Decimal(i)
        }
        return result
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        var result: Float64 = 0.0
        for i in 0..n {
            let numerator = pow(-1.0, i) * pow(x, 2 * i)
            let denominator = factorial(2 * i).toFloat64()
            result += numerator / denominator
        }
        return result
    }

    public func sin(x: Float64): Float64 {
        let rad = x * PI / 180.0
        var result: Float64 = 0.0
        for i in 0..50 {
            let numerator = pow(-1.0, i) * pow(rad, 2 * i + 1)
            let denominator = factorial(2 * i + 1).toFloat64()
            result += numerator / denominator
        }
        return result
    }

    public func tan(x: Float64): Option<Float64> {
        let cosValue = cos(x)
        if abs(cosValue - 0.0) < 0.000001 {
            return None
        }
        let sinValue = sin(x)
        return Some(sinValue / cosValue)
    }
}

