class URLHandler {

    /*
    The class supports to handle URLs, including extracting the scheme, host, path, query parameters, and fragment.
    */

    let url: String

    public init(url: String) {
        /*
        Initialize URLHandler's URL
        */
        this.url = url
    }

    public func get_scheme(): Option<String> {
        /*
        get the scheme of the URL
        :return: Option<String>, If successful, return the scheme of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_scheme()
        "https"
        */
        let index = url.indexOf("://")
        if (index == -1) {
            return Option<String>.none()
        }
        return Option<String>.some(url.substring(0, index))
    }

    public func get_host(): Option<String> {
        /*
        Get the second part of the URL, which is the host domain name
        :return: Option<String>, If successful, return the host domain name of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_host()
        "www.baidu.com"
        */
        let schemeEnd = url.indexOf("://")
        if (schemeEnd == -1) {
            return Option<String>.none()
        }
        let start = schemeEnd + 3
        let end1 = url.indexOf("/", start)
        let end2 = url.indexOf("?", start)
        let end3 = url.indexOf("#", start)
        var end = url.size
        if (end1 != -1 && end1 < end) {
            end = end1
        }
        if (end2 != -1 && end2 < end) {
            end = end2
        }
        if (end3 != -1 && end3 < end) {
            end = end3
        }
        if (end == start) {
            return Option<String>.none()
        }
        return Option<String>.some(url.substring(start, end))
    }

    public func get_path(): Option<String> {
        /*
        Get the third part of the URL, which is the address of the resource
        :return: Option<String>, If successful, return the address of the resource of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_path()
        "/s?wd=aaa&rsv_spt=1#page"
        */
        let schemeEnd = url.indexOf("://")
        var start = 0
        if (schemeEnd != -1) {
            let hostStart = schemeEnd + 3
            let hostEnd1 = url.indexOf("/", hostStart)
            let hostEnd2 = url.indexOf("?", hostStart)
            let hostEnd3 = url.indexOf("#", hostStart)
            var hostEnd = url.size
            if (hostEnd1 != -1) {
                hostEnd = hostEnd1
            }
            if (hostEnd2 != -1 && hostEnd2 < hostEnd) {
                hostEnd = hostEnd2
            }
            if (hostEnd3 != -1 && hostEnd3 < hostEnd) {
                hostEnd = hostEnd3
            }
            start = hostEnd
        } else {
            let firstSlash = url.indexOf("/")
            if (firstSlash == -1) {
                return Option<String>.none()
            }
            start = firstSlash
        }
        if (start >= url.size) {
            return Option<String>.none()
        }
        return Option<String>.some(url.substring(start))
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        /*
        Get the request parameters for the URL
        :return: Option<HashMap<String, String>>, If successful, return the request parameters of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_query_params()
        {"wd": "aaa", "rsv_spt": "1"}
        */
        let question = url.indexOf("?")
        if (question == -1) {
            return Option<HashMap<String, String>>.none()
        }
        let fragment = url.indexOf("#", question)
        let queryEnd = if (fragment == -1) { url.size } else { fragment }
        let query = url.substring(question + 1, queryEnd)
        let pairs = query.split("&")
        let params = HashMap<String, String>()
        for (pair in pairs) {
            if (pair.isEmpty()) {
                continue
            }
            let eq = pair.indexOf("=")
            if (eq == -1) {
                params.add(pair, "")
            } else {
                let key = pair.substring(0, eq)
                let value = pair.substring(eq + 1)
                params.add(key, value)
            }
        }
        return Option<HashMap<String, String>>.some(params)
    }

    public func get_fragment(): Option<String> {
        /*
        Get the fragment after '#' in the URL
        :return: Option<String>, If successful, return the fragment after '#' of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_fragment()
        "page"
        */
        let fragmentIndex = url.lastIndexOf("#")
        if (fragmentIndex == -1 || fragmentIndex == url.size - 1) {
            return Option<String>.none()
        }
        return Option<String>.some(url.substring(fragmentIndex + 1))
    }
}

