import std.collection.ArrayList

class UrlPath {

    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        this.segments.add(segment)
    }

    public func parse(path: String): Unit {
        let fixedPath = UrlPath.fix_path(path)
        if fixedPath.length() > 0 {
            let parts = fixedPath.split("/")
            for part in parts {
                if part.length() > 0 {
                    this.segments.add(part)
                }
            }
        }
        this.with_end_tag = path.length() > 0 && path.at(path.length() - 1) == '/'
    }

    public static func fix_path(path: String): String {
        var start = 0
        var end = path.length()
        while start < end && path.at(start) == '/' {
            start = start + 1
        }
        while end > start && path.at(end - 1) == '/' {
            end = end - 1
        }
        return path.substring(start, end)
    }
}

