    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if vector_list_1.isEmpty || vector_list_2.isEmpty {
            return 0.0
        }
        let avg_vector_1: ArrayList<Float64> = ArrayList<Float64>()
        let avg_vector_2: ArrayList<Float64> = ArrayList<Float64>()
        let dim: Int64 = vector_list_1[0].size
        for i in 0..dim {
            avg_vector_1.add(0.0)
            avg_vector_2.add(0.0)
        }
        for vector in vector_list_1 {
            for i in 0..dim {
                avg_vector_1[i] += vector[i]
            }
        }
        for vector in vector_list_2 {
            for i in 0..dim {
                avg_vector_2[i] += vector[i]
            }
        }
        let count1: Float64 = vector_list_1.size.cast(Float64)
        let count2: Float64 = vector_list_2.size.cast(Float64)
        for i in 0..dim {
            avg_vector_1[i] /= count1
            avg_vector_2[i] /= count2
        }
        return similarity(avg_vector_1, avg_vector_2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result: HashMap<String, Float64> = HashMap<String, Float64>()
        for (key, value) in number_dict {
            let count: Float64 = value
            let weight: Float64 = log((total_num.cast(Float64) + 1.0) / (count + 1.0))
            result.put(key, weight)
        }
        return result
    }
